<style>
  :root {
    --bg: #0f172a;
    --card: #1e293b;
    --card-light: #334155;
    --text: #f1f5f9;
    --text-muted: #94a3b8;
    --accent: #3b82f6;
    --accent-green: #22c55e;
    --accent-red: #ef4444;
    --accent-amber: #f59e0b;
    --border: #334155;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }
  .container { max-width: 1200px; margin: 0 auto; padding: 24px; }
  header {
    border-bottom: 1px solid var(--border);
    padding-bottom: 24px;
    margin-bottom: 32px;
  }
  header h1 { font-size: 1.9rem; font-weight: 700; letter-spacing: -0.02em; }
  header p { color: var(--text-muted); margin-top: 6px; font-size: 1rem; }
  .meta { display: flex; gap: 24px; margin-top: 12px; flex-wrap: wrap; font-size: 0.85rem; color: var(--text-muted); }

  /* KPI Dashboard */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 40px;
  }
  .kpi-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
    text-align: center;
    transition: transform .15s ease;
  }
  .kpi-card:hover { transform: translateY(-2px); }
  .kpi-value {
    font-size: 1.8rem;
    font-weight: 700;
    margin: 8px 0;
  }
  .kpi-label {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--text-muted);
  }
  .kpi-sub {
    font-size: 0.8rem;
    color: var(--text-muted);
    margin-top: 4px;
  }
  .positive { color: var(--accent-green); }
  .negative { color: var(--accent-red); }
  .neutral { color: var(--accent-amber); }

  /* Sections */
  section {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 28px;
    margin-bottom: 28px;
  }
  section h2 {
    font-size: 1.3rem;
    font-weight: 600;
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    gap: 10px;
  }
  section h2::before {
    content: '';
    display: inline-block;
    width: 4px;
    height: 22px;
    background: var(--accent);
    border-radius: 2px;
  }
  section p { color: #cbd5e1; margin-bottom: 12px; font-size: 0.95rem; }

  .chart-container {
    position: relative;
    height: 380px;
    margin: 20px 0;
  }
  .chart-container.tall { height: 480px; }
  .chart-container.wide { height: 320px; }

  /* Tables */
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
    margin-top: 12px;
  }
  th, td {
    padding: 10px 12px;
    text-align: right;
    border-bottom: 1px solid var(--border);
  }
  th { color: var(--text-muted); font-weight: 600; text-transform: uppercase; font-size: 0.7rem; letter-spacing: 0.06em; text-align: right; }
  td:first-child, th:first-child { text-align: left; }
  tr:hover td { background: rgba(255,255,255,0.03); }

  /* Two column layout */
  .two-col {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }
  @media (max-width: 900px) {
    .two-col { grid-template-columns: 1fr; }
    .kpi-grid { grid-template-columns: repeat(2, 1fr); }
  }

  /* Highlight box */
  .highlight-box {
    background: rgba(59,130,246,0.08);
    border-left: 3px solid var(--accent);
    padding: 14px 18px;
