    margin: 14px 0;
    font-size: 0.92rem;
  }

  /* Event timeline */
  .timeline { margin: 16px 0; }
  .timeline-item {
    display: flex;
    gap: 16px;
    padding: 10px 0;
    border-bottom: 1px solid var(--border);
  }
  .timeline-date { min-width: 110px; font-weight: 600; color: var(--accent); font-size: 0.85rem; }
  .timeline-body { flex: 1; font-size: 0.9rem; }
