  const tbody = document.querySelector('#splits-table tbody');
  tbody.innerHTML = splits.map(s => {
    cumulative *= s.ratio;
    return `<tr><td>${s.Date}</td><td>${s.description}</td><td>$${s.Close}</td><td>${cumulative.toFixed(2)}×</td></tr>`;
  }).join('');
}

