function renderDecadeTable(decade) {
  const tbody = document.querySelector('#decade-table tbody');
  tbody.innerHTML = decade.map(d => {
    const cls = d.return >= 0 ? 'positive' : 'negative';
    return `<tr>
      <td style="text-align:left">${d.Decade}s</td>
      <td>$${d.start_price}</td>
      <td>$${d.end_price}</td>
      <td class="${cls}">${d.return>0?'+':''}${d.return}%</td>
      <td class="${d.cagr_pct>=0?'positive':'negative'}">${d.cagr_pct}%</td>
      <td>${d.volatility}%</td>
      <td>$${d.dividends}</td>
      <td>$${d.low} – $${d.high}</td>
    </tr>`;
  }).join('');
}

function renderHeatmap(monthly) {
  const years = [...new Set(monthly.map(m => m.Year))].sort((a,b)=>a-b);
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const container = document.getElementById('heatmap-container');

  let html = '<div style="display:flex;gap:4px;flex-direction:column;">';
  // Header
  html += '<div style="display:grid;grid-template-columns:50px repeat(12,1fr);gap:2px;"><div></div>' + months.map(m => `<span style="font-size:0.65rem;color:#94a3b8;text-align:center;">${m}</span>`).join('') + '</div>';

  years.forEach(y => {
    html += `<div style="display:grid;grid-template-columns:50px repeat(12,1fr);gap:2px;align-items:center;"><span style="font-size:0.7rem;color:#94a3b8;text-align:right;padding-right:6px;">${y}</span>`;
    for (let m = 1; m <= 12; m++) {
      const cell = monthly.find(x => x.Year === y && x.Month === m);
      const val = cell ? cell.return : 0;
      const color = val >= 20 ? '#166534' : val >= 10 ? '#22c55e' : val >= 5 ? '#86efac' : val >= 0 ? '#dcfce7' : val >= -5 ? '#fee2e2' : val >= -10 ? '#fca5a5' : val >= -20 ? '#ef4444' : '#991b1b';
      const textColor = Math.abs(val) > 8 ? '#fff' : '#0f172a';
      html += `<div style="background:${color};color:${textColor};font-size:0.6rem;text-align:center;padding:3px 0;border-radius:2px;" title="${y}-${String(m).padStart(2,'0')}: ${val.toFixed(1)}%">${Math.abs(val)>9?val.toFixed(0):''}</div>`;
    }
    html += '</div>';
  });
  html += '</div>';
  container.innerHTML = html;
}
